/// <summary>
/// Data contract class for transfer order backorder cancellation.
/// </summary>
[DataContract]
class METTransferOrderBackOrderCancelContract extends METSysOperationTaskDataContract
{
    METDaysFromShipDate daysFromShipDate;
    guid topPickingProcessId;

}

Method.Source:
// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// get/set days Number of days after ship date.
/// </summary>
/// <param name = "_daysFromShipDate">
/// Number of days after ship date.
/// </param>
/// <returns></returns>
[DataMember]
public METDaysFromShipDate parmDaysFromShipDate(real _daysFromShipDate = daysFromShipDate)
{
    daysFromShipDate = _daysFromShipDate;
    return daysFromShipDate;
}
